<?php require_once "db.php"; $result=$conn->query("SELECT * FROM patients ORDER BY id DESC"); ?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Patient Records</title><link rel="stylesheet" href="style.css"></head><body><?php include "header.php"; ?><main class="container"><h2>Patient Records</h2><p>Registered patient details from MySQL.</p><div style="overflow-x:auto"><table><tr><th>ID</th><th>Name</th><th>Email</th><th>Phone</th><th>Gender</th><th>Address</th><th>Image</th></tr>
